  mem_grows M M' -> L5.u32_at RSEGS M' (ov + 48) d' -> 0 <= d' <= MAX_DEPTH + 1 ->
  PECA.enc_atA RSEGS EE L ar M' ov fb (PEC.ENC eb ek stk d').
