Section Frame.
Variables (F fl : Z) (LK2 : list fframe) (M2 : word -> option byte) (model2 : Model).
Let G_ := PMAUK.gctx L ar HI LBc0 FF LK Aw sp 20480 spc (sp - 8 * NSV) sp (ocell sp NSV) (owns SAVED sp R) F fl 1 LK2 M2 model2 cr (EBX k).
Hypothesis G : G_.
